import{c as t,Q as a,j as r,m as s}from"./chunks/framework.DGHXLY8X.js";const o="/videonode/screenshots/streams-empty.png",n="/videonode/screenshots/new-source.png",i="/videonode/screenshots/sources-list.png",c="/videonode/screenshots/new-stream.png",b=JSON.parse('{"title":"Quickstart","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/quickstart.md","filePath":"getting-started/quickstart.md","lastUpdated":1780006480000}'),p={name:"getting-started/quickstart.md"};function l(d,e,u,h,m,g){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="quickstart" tabindex="-1">Quickstart <a class="header-anchor" href="#quickstart" aria-label="Permalink to &quot;Quickstart&quot;">​</a></h1><p>This tutorial takes you from a running VideoNode installation to a live stream playing in your browser. It assumes you&#39;ve completed <a href="./installation">Installation</a>.</p><h2 id="step-1-open-the-ui" tabindex="-1">Step 1: Open the UI <a class="header-anchor" href="#step-1-open-the-ui" aria-label="Permalink to &quot;Step 1: Open the UI&quot;">​</a></h2><p>Browse to <code>http://&lt;your-box&gt;:8090</code> (or <code>http://localhost:8090</code> if you&#39;re on the box itself). The login page appears. Sign in with your Linux username and password (or the basic-auth credentials, if you switched to that during install).</p><p>You&#39;ll land on the <strong>Streams</strong> page, empty on a fresh install:</p><p><img src="'+o+'" alt="Empty streams page with a Create Stream button"></p><h2 id="step-2-create-a-source" tabindex="-1">Step 2: Create a source <a class="header-anchor" href="#step-2-create-a-source" aria-label="Permalink to &quot;Step 2: Create a source&quot;">​</a></h2><p>A <em>source</em> is the upstream that produces frames: a real V4L2 device or a built-in test pattern. Click <strong>Sources</strong> in the nav, then <strong>New source</strong>.</p><p><img src="'+n+'" alt="New source form: ID field, test-mode checkbox, video device dropdown, format / resolution / framerate selectors"></p><p>Pick a Source ID (kebab-case), select your capture device from the <strong>Video Device</strong> dropdown, and pick a format, resolution, and framerate. If you don&#39;t have hardware plugged in yet, tick <strong>Test mode</strong> to use the built-in test-pattern producer instead. Click <strong>Create Source</strong>.</p><p>The source appears in the table with status <strong>Running</strong> and consumer count <code>0</code>. It&#39;s broadcasting frames but no one is listening yet.</p><p><img src="'+i+'" alt="Sources page showing a running test source"></p><h2 id="step-3-create-a-stream" tabindex="-1">Step 3: Create a stream <a class="header-anchor" href="#step-3-create-a-stream" aria-label="Permalink to &quot;Step 3: Create a stream&quot;">​</a></h2><p>A <em>stream</em> pairs an upstream (your new source) with an encoder and a publish target. Click <strong>Streams</strong>, then <strong>Create Stream</strong>.</p><p><img src="'+c+'" alt="New stream form: stream ID, upstream selector, encoder fields, audio block"></p><p>Set:</p><ul><li><strong>Stream ID</strong>: anything kebab-case; this becomes the URL path component for RTSP/SRT/WebRTC consumers.</li><li><strong>Upstream</strong>: pick your source from the dropdown.</li><li><strong>Codec</strong>: <code>H.264</code> for widest compatibility.</li><li><strong>Bitrate</strong>: <code>2M</code> is a reasonable default for 1080p.</li></ul><p>Leave the rest at defaults and click <strong>Create Stream</strong>. The stream appears in the Streams table.</p><h2 id="step-4-watch-the-stream" tabindex="-1">Step 4: Watch the stream <a class="header-anchor" href="#step-4-watch-the-stream" aria-label="Permalink to &quot;Step 4: Watch the stream&quot;">​</a></h2><p>The Streams page renders a live WebRTC preview as soon as you click the row. To open the stream in an external player, see <a href="./../operating/streaming-outputs">Streaming outputs</a> for the RTSP / SRT / WebRTC URL formats and example consumer commands.</p>',20)])])}const S=t(p,[["render",l]]);export{b as __pageData,S as default};
